#include "dfre/mission_line_file_runtime.hpp"
#include <iostream>
#include <map>
#include <sstream>
using U=std::uint32_t;
int main(){try{std::string line;while(std::getline(std::cin,line)){std::istringstream input(line);U limit,flags,mutation,n;input>>limit>>flags>>mutation>>n;std::vector<U> chars(n);for(auto& c:chars)input>>c;if(!input)throw std::runtime_error("Incomplete FILE case");std::map<U,std::uint8_t> memory;constexpr U file=0x2201000,out=0x2202000;for(U i=0;i<32;++i)memory[file+i]=0;for(U i=0;i<2048;++i)memory[out+i]=0xa5;const auto put=[&](U at,U size,U value){for(U i=0;i<size;++i)memory.at(at+i)=std::uint8_t(value>>(i*8));};const auto get=[&](U at,U size){U value=0;for(U i=0;i<size;++i)value|=U(memory.at(at+i))<<(i*8);return value;};put(file+12,4,flags);put(file+16,4,7);std::string trace;U index=0;dfre::MissionLineFileBindings b;b.read=[&](U at,U size){const auto value=get(at,size);trace+="R,"+std::to_string(at)+","+std::to_string(size)+","+std::to_string(value)+";";return value;};b.write=[&](U at,U size,U value){trace+="W,"+std::to_string(at)+","+std::to_string(size)+","+std::to_string(value)+";";put(at,size,value);};b.call=[&](U site,const std::vector<U>& a)->U{trace+="C,"+std::to_string(site)+","+std::to_string(a.at(0))+";";if(site==0x501d64){if(mutation&1)put(file+12,4,get(file+12,4)^0x30);return 0;}if(site==0x501d68)return 0;if(site==0x4ba3c0){const auto c=index<chars.size()?chars[index]:0xffffffffu;++index;if(c==0xffffffffu)put(file+12,1,get(file+12,1)|((mutation&2)?0x20:0x10));if((mutation&4)&&index==1)put(file+16,4,19);return c;}throw std::runtime_error("Unknown FILE fixture");};const auto result=dfre::mission_line_file_read(b,out,limit,file);std::uint64_t hash=1469598103934665603ull;for(const auto& byte:memory){hash^=byte.second;hash*=1099511628211ull;}std::cout<<result<<' '<<hash<<' '<<trace<<'\n';}return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
